import {
  ME_ID,
  type ChatDirectory,
  type Conversation,
  type Message,
  type Person,
} from "./types";
import {
  appendMessage,
  findConversation,
  markConversationRead,
  mutateStore,
  otherMemberIds,
  readStore,
  writeStore,
} from "./storage";
import { delay, pickMany, randomInt } from "./random";
import { getPersona } from "./personas";
import { HISTORY_LIMIT, type HistoryTurn, type ReplyRequest } from "./reply";

/**
 * Chat API.
 *
 * Reads and writes go to localStorage; reply *text* is generated by Gemini
 * through `POST /api/chat/reply`, which keeps the API key on the server. When
 * Gemini is unavailable each persona falls back to its own canned lines, so the
 * app keeps working — and Maya still sounds like Maya rather than picking a line
 * from a shared pool.
 *
 * Every function is async and deliberately slow, so the UI has real loading
 * states to render.
 */

/** Simulated latency for reads. */
const FETCH_LATENCY = { min: 140, max: 340 } as const;
/** Time between "sent" and the first reply arriving. */
const FIRST_REPLY_LATENCY = { min: 700, max: 1500 } as const;
/** Gap between consecutive replies in a group chat. */
const NEXT_REPLY_LATENCY = { min: 550, max: 1400 } as const;
/** Keeps a large group from burying your message under replies. */
const MAX_GROUP_REPLIERS = 3;

export function createMessageId(): string {
  return `msg-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Label used for messages sent right now. */
export function nowLabel(): string {
  return "Just now";
}

export async function fetchDirectory(): Promise<ChatDirectory> {
  await delay(randomInt(FETCH_LATENCY.min, FETCH_LATENCY.max));
  const store = readStore();
  return {
    me: store.me,
    people: store.people,
    conversations: store.conversations,
  };
}

export async function fetchMessages(conversationId: string): Promise<Message[]> {
  await delay(randomInt(FETCH_LATENCY.min, FETCH_LATENCY.max));
  return readStore().messages[conversationId] ?? [];
}

/** Clears the unread badge for a conversation. Returns true when it changed. */
export function markRead(conversationId: string): boolean {
  return mutateStore((store) => markConversationRead(store, conversationId));
}

export interface ReplyPlan {
  authorId: string;
  /** Milliseconds after the outgoing message before this reply should land. */
  delayMs: number;
}

/**
 * Decides who answers and when. The *text* now comes from the persona, so this
 * only chooses people and timing.
 *
 * Direct messages always get exactly one reply from the other person. Group
 * chats get a random number of distinct responders, each with their own arrival
 * time.
 */
export function planReplies(conversation: Conversation): ReplyPlan[] {
  const responders = otherMemberIds(conversation);
  if (responders.length === 0) return [];

  const count =
    conversation.kind === "group"
      ? randomInt(1, Math.min(responders.length, MAX_GROUP_REPLIERS))
      : 1;

  let elapsed = 0;
  return pickMany(responders, count).map((authorId, index) => {
    elapsed +=
      index === 0
        ? randomInt(FIRST_REPLY_LATENCY.min, FIRST_REPLY_LATENCY.max)
        : randomInt(NEXT_REPLY_LATENCY.min, NEXT_REPLY_LATENCY.max);

    return { authorId, delayMs: elapsed };
  });
}

export interface SendMessageHandlers {
  /** Fired once the outgoing message is persisted. */
  onSent?: (message: Message) => void;
  /** Fired when somebody starts typing, and again when they stop. */
  onTypingStart?: (authorId: string) => void;
  onTypingEnd?: (authorId: string) => void;
  /** Fired as each reply lands. */
  onReply?: (message: Message) => void;
}

/** Who is in the conversation, and what has been said so far. */
export interface ReplyContext {
  conversation: Conversation;
  people: Person[];
  me: Person;
  /** The thread so far, oldest first. */
  history: Message[];
}

export interface SendMessageInput {
  conversationId: string;
  text: string;
  /**
   * Client generated id (an idempotency key) so the optimistic bubble can be
   * reconciled with the stored message instead of being duplicated.
   */
  id: string;
  /** Everything the personas need to answer in character. */
  context: ReplyContext;
}

export interface SendMessageResult {
  message: Message;
  replies: Message[];
}

/** Rotates through a persona's canned lines so repeats are never back-to-back. */
const fallbackCursors = new Map<string, number>();
let hasWarnedAboutFallback = false;

function warnOnce(reason: string) {
  if (hasWarnedAboutFallback) return;
  hasWarnedAboutFallback = true;
  console.warn(
    `[chat] Gemini replies unavailable (${reason}); using in-character fallback lines. ` +
      "Set GEMINI_API_KEY to enable generated replies.",
  );
}

function nameOf(people: Person[], me: Person, id: string): string {
  if (id === ME_ID) return me.name;
  return people.find((person) => person.id === id)?.name ?? id;
}

/** One in-character line, used when Gemini cannot be reached. */
export function fallbackReply(authorId: string): string {
  const lines = getPersona(authorId)?.fallbackLines ?? ["Got it."];
  const next = (fallbackCursors.get(authorId) ?? -1) + 1;
  fallbackCursors.set(authorId, next % lines.length);
  return lines[next % lines.length];
}

/**
 * Asks the server for one persona's reply, falling back to that persona's own
 * canned lines when Gemini is unavailable.
 */
async function generateReply(input: {
  conversation: Conversation;
  people: Person[];
  me: Person;
  history: Message[];
  prompt: string;
  authorId: string;
}): Promise<string> {
  const { conversation, people, me, history, prompt, authorId } = input;

  const request: ReplyRequest = {
    conversationId: conversation.id,
    kind: conversation.kind,
    conversationName: conversation.name,
    authorId,
    authorName: nameOf(people, me, authorId),
    members: conversation.memberIds.map((id) => ({
      id,
      name: nameOf(people, me, id),
    })),
    prompt,
    history: history
      .slice(-HISTORY_LIMIT)
      .map((message): HistoryTurn => ({
        authorId: message.authorId,
        authorName: nameOf(people, me, message.authorId),
        text: message.text,
      })),
  };

  try {
    const response = await fetch("/api/chat/reply", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(request),
    });

    if (!response.ok) {
      const detail = (await response.json().catch(() => null)) as
        | { reason?: string }
        | null;
      warnOnce(detail?.reason ?? `HTTP ${response.status}`);
      return fallbackReply(authorId);
    }

    const data = (await response.json()) as { text?: string };
    const text = data.text?.trim();
    return text ? text : fallbackReply(authorId);
  } catch (error) {
    warnOnce(error instanceof Error ? error.message : "network error");
    return fallbackReply(authorId);
  }
}

/**
 * Persists the outgoing message, then streams the replies in.
 *
 * The returned promise only resolves once every reply has landed, which is what
 * lets the UI keep the composer disabled until the conversation goes quiet.
 */
export async function sendMessage(
  input: SendMessageInput,
  handlers: SendMessageHandlers = {},
): Promise<SendMessageResult> {
  const text = input.text.trim();
  if (!text) throw new Error("Cannot send an empty message");

  const store = readStore();
  const conversation = findConversation(store, input.conversationId);
  if (!conversation) throw new Error(`Unknown conversation: ${input.conversationId}`);

  const message = appendMessage(store, {
    id: input.id,
    conversationId: input.conversationId,
    authorId: ME_ID,
    text,
    time: nowLabel(),
    status: "sent",
  });
  writeStore(store);
  handlers.onSent?.(message);

  await delay(randomInt(180, 420));

  const plan = planReplies(conversation);
  for (const entry of plan) handlers.onTypingStart?.(entry.authorId);

  // Generation latency dominates, so every responder is asked at once and the
  // results are released in their scheduled order below.
  const pending = plan.map((entry) =>
    generateReply({
      conversation,
      people: input.context.people,
      me: input.context.me,
      history: input.context.history,
      prompt: text,
      authorId: entry.authorId,
    }),
  );

  const replies: Message[] = [];
  let waited = 0;

  // Replies are appended one at a time, in arrival order, so concurrent writes
  // can never clobber each other in localStorage.
  for (const [index, entry] of plan.entries()) {
    await delay(Math.max(0, entry.delayMs - waited));
    waited = Math.max(waited, entry.delayMs);

    let replyText: string;
    try {
      replyText = await pending[index];
    } catch (error) {
      // One persona failing should not sink the whole send.
      console.error(`[chat] reply from ${entry.authorId} failed`, error);
      handlers.onTypingEnd?.(entry.authorId);
      continue;
    }

    const reply = mutateStore((current) =>
      appendMessage(current, {
        id: createMessageId(),
        conversationId: input.conversationId,
        authorId: entry.authorId,
        text: replyText,
        time: nowLabel(),
      }),
    );

    handlers.onTypingEnd?.(entry.authorId);
    handlers.onReply?.(reply);
    replies.push(reply);
  }

  if (replies.length === 0 && plan.length > 0) {
    throw new Error("No replies could be generated");
  }

  return { message, replies };
}
